    <div id="confirmModal" class="app-modal" role="dialog" aria-modal="true"><div class="modal-panel max-w-lg"><div class="modal-heading"><div><p class="modal-kicker">Confirmar operación</p><h2 class="modal-title">¿Seguro que quieres realizar la venta?</h2><p class="mt-2 text-sm leading-6 text-slate-500">Se reservará un correlativo y el comprobante será enviado a SUNAT.</p></div><button type="button" data-close-confirm class="modal-close">×</button></div><div id="confirmSummary" class="mt-6 rounded-md bg-slate-50 p-4 text-sm dark:bg-white/5"></div><div class="modal-actions"><button type="button" data-close-confirm class="admin-secondary-button">No, revisar</button><button type="button" id="ejecutarVenta" class="admin-primary-button">Sí, emitir</button></div></div></div>

    <div id="saleSuccessModal" class="app-modal" role="dialog" aria-modal="true"><div class="modal-panel max-w-lg text-center"><div class="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#eaff00] text-3xl font-bold text-black">✓</div><p class="modal-kicker mt-6">Operación completada</p><h2 class="modal-title">Comprobante emitido</h2><p id="successSaleNumber" class="mt-2 font-mono text-sm font-bold"></p><p class="mt-3 text-sm leading-6 text-slate-500">El PDF permanece protegido. Solo se carga en memoria cuando eliges imprimir o compartir.</p><div id="successAlert" class="form-alert mt-5 hidden"></div><div class="mt-7 grid gap-3 sm:grid-cols-3"><button type="button" id="closeSuccess" class="admin-secondary-button">Cerrar</button><button type="button" id="shareSuccess" class="admin-secondary-button">Compartir</button><button type="button" id="printSuccess" class="admin-primary-button">Imprimir</button></div></div></div>

    <div id="saleLoader" class="sale-loader hidden" aria-live="assertive"><div class="sale-loader-card"><span class="sale-spinner"></span><strong id="saleLoaderTitle">Emitiendo comprobante…</strong><p>No cierres esta ventana. Estamos comunicándonos con SUNAT.</p></div></div>

    <script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script>
    <script>
    const cart=[],money=new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}),empresa=document.getElementById('empresa'),tipo=document.getElementById('tipoComprobante'),serie=document.getElementById('serie'),docType=document.getElementById('tipoDocumento'),docNumber=document.getElementById('numeroDocumento'),clientName=document.getElementById('clienteNombre'),clientAddress=document.getElementById('clienteDireccion');
    document.getElementById('theme-toggle')?.addEventListener('click',()=>{const d=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',d);localStorage.setItem('landing-theme',d?'dark':'light')});
    const setMessage=(id,state,msg)=>{const el=document.getElementById(id);el.dataset.state=state;el.textContent=msg;el.classList.remove('hidden')};
    async function fetchJson(url,options={},timeout=15000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(url,{...options,signal:controller.signal,headers:{Accept:'application/json',...(options.headers||{})}}),json=await response.json();if(!response.ok||!json.success)throw new Error(json.error?.message||'La operación no pudo completarse.');return json.data}finally{clearTimeout(timer)}}
    async function loadSeries(){serie.innerHTML='<option value="">Cargando series…</option>';try{const rows=await fetchJson(`/api/facturacion/pos/series?empresa_id=${empresa.value}`),filtered=rows.filter(row=>row.tipo_comprobante===tipo.value);serie.innerHTML=filtered.length?filtered.map(row=>`<option value="${escapeHtml(row.serie)}">${escapeHtml(row.serie)} · siguiente ${String(Number(row.correlativo)+1).padStart(8,'0')}</option>`).join(''):'<option value="">Sin serie configurada</option>'}catch(e){serie.innerHTML='<option value="">No se pudieron cargar</option>';setMessage('saleAlert','error',e.message)}}
    empresa?.addEventListener('change',()=>{cart.splice(0);drawCart();loadSeries();resetProductSelect()});tipo?.addEventListener('change',()=>{docType.value=tipo.value==='01'?'6':'1';syncDocument();loadSeries()});docType?.addEventListener('change',syncDocument);function syncDocument(){docNumber.value='';docNumber.maxLength=docType.value==='6'?11:8;docNumber.placeholder=docType.value==='6'?'20123456789':'12345678';clientName.value='';clientAddress.value=''}
    function resetProductSelect(){if(!window.jQuery)return;$('#productoSelect').val(null).trigger('change')}
    if(window.jQuery&&$.fn.select2){$('#productoSelect').select2({placeholder:'Escribe un código o nombre…',minimumInputLength:0,width:'100%',ajax:{url:'/api/facturacion/pos/productos',dataType:'json',delay:250,data:params=>({empresa_id:empresa.value,q:params.term||'',page:params.page||1}),processResults:response=>response.data,cache:true},templateResult:item=>item.loading?item.text:$(`<div><strong>${$('<span>').text(item.codigo).html()}</strong><span class="block text-xs text-slate-500">${$('<span>').text(item.descripcion).html()} · S/ ${money.format(item.precio_unitario)}</span></div>`),escapeMarkup:markup=>markup})}
    document.getElementById('agregarProducto')?.addEventListener('click',()=>{const item=$('#productoSelect').select2('data')[0];if(!item||!item.id)return;const existing=cart.find(row=>String(row.id)===String(item.id));if(existing)existing.cantidad+=1;else cart.push({...item,cantidad:1,precio_unitario:Number(item.precio_unitario)});resetProductSelect();drawCart()});
    function drawCart(){const body=document.getElementById('detalleBody');body.innerHTML='';if(!cart.length){body.innerHTML='<tr><td colspan="5" class="py-10 text-center text-sm text-slate-400">Agrega el primer producto para iniciar la venta.</td></tr>'}cart.forEach((item,index)=>{const row=document.createElement('tr');row.className='border-b border-slate-100 dark:border-white/5';row.innerHTML=`<td class="px-2 py-3"><strong class="block text-sm">${escapeHtml(item.descripcion)}</strong><code class="text-xs text-slate-400">${escapeHtml(item.codigo)} · ${escapeHtml(item.unidad)}</code></td><td class="px-2 py-3"><input class="field-input !px-2 !py-2" type="number" min="0.001" step="0.001" value="${item.cantidad}" data-qty="${index}"></td><td class="px-2 py-3"><input class="field-input !px-2 !py-2" type="number" min="0" step="0.01" value="${item.precio_unitario.toFixed(2)}" data-price="${index}"></td><td class="px-2 py-3 text-right font-semibold">${money.format(item.cantidad*item.precio_unitario)}</td><td><button type="button" class="text-lg text-red-500" data-remove="${index}" aria-label="Quitar">×</button></td>`;body.appendChild(row)});body.querySelectorAll('[data-qty]').forEach(input=>input.addEventListener('change',()=>{cart[input.dataset.qty].cantidad=Math.max(.001,Number(input.value)||1);drawCart()}));body.querySelectorAll('[data-price]').forEach(input=>input.addEventListener('change',()=>{cart[input.dataset.price].precio_unitario=Math.max(0,Number(input.value)||0);drawCart()}));body.querySelectorAll('[data-remove]').forEach(button=>button.addEventListener('click',()=>{cart.splice(button.dataset.remove,1);drawCart()}));calculateTotals()}
    function calculateTotals(){let subtotal=0,igv=0,total=0;cart.forEach(item=>{const amount=item.cantidad*item.precio_unitario;total+=amount;if(['10','21'].includes(item.afectacion_igv)){const base=amount/1.18;subtotal+=base;igv+=amount-base}else subtotal+=amount});document.getElementById('subtotal').textContent=`S/ ${money.format(subtotal)}`;document.getElementById('igv').textContent=`S/ ${money.format(igv)}`;document.getElementById('total').textContent=`S/ ${money.format(total)}`;return total}
    const escapeHtml=value=>{const div=document.createElement('div');div.textContent=value??'';return div.innerHTML};
    document.getElementById('buscarDocumento')?.addEventListener('click',async()=>{const number=docNumber.value.trim(),kind=docType.value==='6'?'ruc':'dni',length=kind==='ruc'?11:8;if(!new RegExp(`^\\d{${length}}$`).test(number)){setMessage('documentoAlert','error',`${kind.toUpperCase()} debe tener ${length} dígitos.`);return}setMessage('documentoAlert','loading','Consultando documento…');try{const data=await fetchJson(`/api/facturacion/pos/documentos/${kind}/${number}`);clientName.value=data.nombre||clientName.value;clientAddress.value=data.direccion||clientAddress.value;setMessage('documentoAlert','success','Datos encontrados. Puedes corregirlos manualmente antes de emitir.')}catch(e){setMessage('documentoAlert','error',`${e.name==='AbortError'?'La consulta excedió el tiempo de espera.':e.message} Puedes completar los datos manualmente.`)}});
    const modal=document.getElementById('confirmModal');document.querySelectorAll('[data-close-confirm]').forEach(button=>button.addEventListener('click',()=>{modal.classList.remove('flex');document.body.style.overflow=''}));
    document.getElementById('confirmarVenta')?.addEventListener('click',()=>{if(!serie.value){setMessage('saleAlert','error','Configura y selecciona una serie.');return}const length=docType.value==='6'?11:8;if(!new RegExp(`^\\d{${length}}$`).test(docNumber.value.trim())){setMessage('saleAlert','error',`El documento debe tener ${length} dígitos.`);return}if(!clientName.value.trim()){setMessage('saleAlert','error','Ingresa los nombres o razón social del cliente.');return}if(!cart.length){setMessage('saleAlert','error','Agrega al menos un producto.');return}document.getElementById('confirmSummary').innerHTML=`<div class="flex justify-between"><span>Cliente</span><strong class="text-right">${escapeHtml(clientName.value)}</strong></div><div class="mt-2 flex justify-between"><span>Comprobante</span><strong>${tipo.options[tipo.selectedIndex].text} · ${escapeHtml(serie.value)}</strong></div><div class="mt-2 flex justify-between"><span>Total</span><strong>S/ ${money.format(calculateTotals())}</strong></div>`;modal.classList.add('flex');document.body.style.overflow='hidden'});
    let completedSale=null,completedPdfCache={};
    const successModal=document.getElementById('saleSuccessModal');
    function toggleSaleLoader(show,title='Emitiendo comprobante…'){document.getElementById('saleLoaderTitle').textContent=title;document.getElementById('saleLoader').classList.toggle('hidden',!show);document.body.classList.toggle('overflow-hidden',show);if(!show)document.body.style.overflow=''}
    document.getElementById('ejecutarVenta')?.addEventListener('click',async()=>{const button=document.getElementById('ejecutarVenta');button.disabled=true;button.textContent='Procesando…';const payload={empresa_id:Number(empresa.value),tipo_comprobante:tipo.value,serie:serie.value,moneda:document.getElementById('moneda').value,cliente:{tipo_documento:docType.value,numero_documento:docNumber.value.trim(),nombre:clientName.value.trim(),direccion:clientAddress.value.trim()},items:cart.map(item=>({codigo:item.codigo,descripcion:item.descripcion,unidad:item.unidad,cantidad:item.cantidad,precio_unitario:item.precio_unitario,afectacion_igv:item.afectacion_igv}))};let createdId=null;modal.classList.remove('flex');toggleSaleLoader(true,'Creando comprobante…');try{const created=await fetchJson('/api/facturacion/pos/comprobantes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},30000);createdId=created.id;toggleSaleLoader(true,`Enviando ${created.numero} a SUNAT…`);const processed=await fetchJson(`/api/facturacion/pos/comprobantes/${created.id}/procesar`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({empresa_id:Number(empresa.value)})},130000);completedSale={...processed,empresa_id:Number(empresa.value),formato:document.getElementById('formato').value};completedPdfCache={};toggleSaleLoader(true,'Protegiendo PDF en memoria…');try{completedPdfCache.a4=await getCompletedPdf('a4');if(completedSale.formato!=='a4')completedPdfCache[completedSale.formato]=await getCompletedPdf(completedSale.formato)}catch(_){}toggleSaleLoader(false);document.getElementById('successSaleNumber').textContent=`${processed.numero} · ${processed.estado}`;document.getElementById('successAlert').classList.add('hidden');successModal.classList.add('flex');document.body.style.overflow='hidden';cart.splice(0);drawCart();clientName.value='';clientAddress.value='';docNumber.value='';await loadSeries()}catch(e){toggleSaleLoader(false);const timedOut=e.name==='AbortError';setMessage('saleAlert','error',timedOut&&createdId?`El envío excedió el tiempo de espera. El comprobante quedó creado con ID ${createdId}; no vuelvas a emitirlo hasta revisar su estado.`:(timedOut?'La operación excedió el tiempo de espera. Intenta nuevamente.':e.message))}finally{button.disabled=false;button.textContent='Sí, emitir'}});
    function successMessage(state,message){const el=document.getElementById('successAlert');el.dataset.state=state;el.textContent=message;el.classList.remove('hidden')}
    async function getCompletedPdf(format){if(completedPdfCache[format])return completedPdfCache[format];if(!completedSale)throw new Error('No hay un comprobante disponible.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(`${completedSale.print_url}&formato=${format}`,{signal:controller.signal});if(!response.ok){let message='PDF no disponible.';try{message=(await response.json()).error?.message||message}catch(_){}throw new Error(message)}const blob=await response.blob();completedPdfCache[format]=blob;return blob}finally{clearTimeout(timer)}}
    async function printCompleted(){const popup=window.open('','impresion-comprobante','popup=yes,width=430,height=720,toolbar=no,location=no,menubar=no,status=no,resizable=yes,scrollbars=no');if(!popup){successMessage('error','El navegador bloqueó la ventana de impresión. Habilita ventanas emergentes e inténtalo nuevamente.');return}popup.document.write('<title>Preparando impresión</title><body style="font-family:sans-serif;display:grid;place-items:center;height:90vh">Preparando impresión…</body>');toggleSaleLoader(true,'Preparando impresión…');try{const blob=await getCompletedPdf(completedSale.formato),url=URL.createObjectURL(blob);popup.location.replace(url);setTimeout(()=>{try{popup.focus();popup.print()}finally{setTimeout(()=>URL.revokeObjectURL(url),60000)}},1200)}catch(error){popup.close();successMessage('error',error.name==='AbortError'?'La descarga del PDF excedió el tiempo de espera.':error.message)}finally{toggleSaleLoader(false);document.body.style.overflow='hidden'}}
    async function shareCompleted(){toggleSaleLoader(true,'Preparando archivo para compartir…');try{const blob=await getCompletedPdf('a4'),file=new File([blob],`${completedSale.numero}.pdf`,{type:'application/pdf'});if(!navigator.share||!navigator.canShare?.({files:[file]}))throw new Error('Este navegador no permite compartir archivos. Usa un celular compatible.');await navigator.share({files:[file],title:`Comprobante ${completedSale.numero}`,text:'Comprobante electrónico'});successMessage('success','PDF compartido correctamente.')}catch(error){if(error.name==='AbortError')successMessage('error','La descarga del PDF excedió el tiempo de espera.');else if(error.name!=='NotAllowedError')successMessage('error',error.message)}finally{toggleSaleLoader(false);document.body.style.overflow='hidden'}}
    document.getElementById('printSuccess').addEventListener('click',printCompleted);document.getElementById('shareSuccess').addEventListener('click',shareCompleted);document.getElementById('closeSuccess').addEventListener('click',()=>{successModal.classList.remove('flex');document.body.style.overflow=''});
    if(empresa){loadSeries();syncDocument();drawCart()}
    </script>
</body></html>
